import {SCOUT_GATE} from './perimeter.js';
import {Renderer,W,H,atBreakfast} from './renderer.js';
import {BUILDINGS,WORLD} from './engine.js';

export class ColonyRenderer extends Renderer{
 // Expedition places are played on their own maps (Update 31), so the farm map no longer draws them.
 drawBuilding(g,id,s,t,level=s.buildings[id]){const b=BUILDINGS[id];if(id==='barn'){this.rect(g,138,112,132,8,'#b99560');for(let i=0;i<Math.min(6,Math.ceil(s.hay/10));i++){this.rect(g,105+i*13,250,12,12,'#ceac60');this.rect(g,108+i*13,250,2,12,'#7c683b');}if(level>=2){this.rect(g,125,168,160,5,'#839085');}if(level>=3){this.rect(g,171,171,5,66,'#8b9590');this.rect(g,232,171,5,66,'#8b9590');}return;}
 if(id==='clinic'||id==='radio'){this.building(g,b.x,b.y,b.w,b.h,id==='clinic'?'#b4b29b':'#7d765e','#556156');this.rect(g,b.x+12,b.y+b.h-30,18,30,'#443b2e');if(id==='clinic'){this.rect(g,b.x+b.w-31,b.y+24,18,18,'#d1c6a1');this.rect(g,b.x+b.w-24,b.y+25,4,16,'#ab5945');this.rect(g,b.x+b.w-30,b.y+31,16,4,'#ab5945');}else{this.rect(g,b.x+b.w-18,b.y-65,3,82,'#8f9992');for(let y=0;y<3;y++)this.rect(g,b.x+b.w-29-y*4,b.y-65+y*16,26+y*8,2,'#9da79e');if(level>=2&&Math.sin(t*3)>0)this.rect(g,b.x+b.w-20,b.y-69,6,6,'#ffd772');}return;}super.drawBuilding(g,id,s,t,level);}
 crop(g,p,t,type){if(p.crop==='potato'){if(p.growth<0)return super.crop(g,p,t,type);const h=5+p.growth*10;for(const off of [-10,0,10]){this.rect(g,p.x+off,p.y-h,3,h+6,'#6f9046');this.rect(g,p.x+off-4,p.y-h,11,5,'#8ba357');if(p.growth>=1)this.rect(g,p.x+off-1,p.y+4,7,4,'#c6ad77');}return;}return super.crop(g,p,t,p.crop&&p.crop!=='auto'?p.crop:type);}
 actor(g,a,farmer,t,tool){if(a.boss){g.save();g.translate(a.x,a.y);g.scale(1.5,1.5);super.actor(g,{...a,x:0,y:0},false,t);g.restore();g.font='bold 10px monospace';g.fillStyle='#f5aa75';g.textAlign='center';g.fillText('COLOSSUS',a.x,a.y-63);g.textAlign='left';return;}if(a.kind==='crawler'){this.rect(g,a.x-14,a.y-7,21,10,'#576b51');this.rect(g,a.x+7,a.y-10,9,9,'#a6b07a');for(let i=0;i<3;i++)this.rect(g,a.x-12+i*7,a.y+3+Math.sin(t*8+i)*2,4,3,'#344333');return;}super.actor(g,a,farmer,t,tool);if(a.kind==='spitter'){this.rect(g,a.x-9,a.y-25,17,7,'#9cac63');this.rect(g,a.x+6,a.y-21,8,5,'#d4e694');}if(a.kind==='screamer'){this.rect(g,a.x-8,a.y-16,16,10,'#a4625c');this.rect(g,a.x-4,a.y-22,8,6,'#522e28');if(a.screamed){g.strokeStyle='#e5a07966';g.beginPath();g.arc(a.x,a.y,22+Math.sin(t*5)*4,0,Math.PI*2);g.stroke();}}}
 fencePiece(g,f,...args){if(f.kind==='gate'&&f.open){if(f.vertical){this.rect(g,f.x,f.y-8,5,18,'#b6ad8e');this.rect(g,f.x,f.y+f.h-8,5,18,'#b6ad8e');}else{this.rect(g,f.x-2,f.y-16,6,25,'#b6ad8e');this.rect(g,f.x+f.w-4,f.y-16,6,25,'#b6ad8e');}return;}super.fencePiece(g,f,...args);if(f.kind==='gate'){this.rect(g,f.x-3,f.y-18,7,27,'#b6ad8e');this.rect(g,f.x+f.w-3,f.y-18,7,27,'#b6ad8e');if(!f.open)this.rect(g,f.x,f.y-13,f.w,4,'#7d8b81');else{this.rect(g,f.x,f.y-13,7,4,'#8cad75');this.rect(g,f.x+f.w-7,f.y-13,7,4,'#8cad75');}}}
 trap(g,tr,t,alpha=1,tint=''){if(tr.kind==='gate')return this.fencePiece(g,{...tr,kind:'gate'},alpha,tint);return super.trap(g,tr,t,alpha,tint);}
 render(s,t,opts={}){super.render(s,t,opts);if(s.mode==='title'||atBreakfast(s))return;const g=this.ctx,v=this.view,k=v.scale;g.save();this.setTransform(g,k,0,0,k,-v.x*k,-v.y*k);if(opts.fenceLine){const line=opts.fenceLine;for(const p of line.points){const color=p.valid?'#b7d486':'#e07a5f';this.fencePiece(g,{...p.rect,vertical:p.vertical},.65,color);g.strokeStyle=color;g.strokeRect(p.rect.x,p.rect.y,p.rect.w,p.rect.h);}const point=line.points.at(-1);if(point){g.fillStyle=line.valid&&s.scrap>=line.cost?'#ffe6a5':'#f59c80';g.font='bold 14px monospace';g.fillText(line.points.length+' fences · '+line.cost+' scrap'+(line.valid?'':' · BLOCKED'),point.x,point.y-35);}}g.lineWidth=1.5/k;g.setLineDash([7/k,5/k]);for(const p of s.people){if(!opts.selected?.has(p.id)||p.away)continue;const points=[{x:p.x,y:p.y},...(p.waypoint?[p.waypoint]:[]),...(p.order?.x!==undefined?[p.order]:[]),...p.orders.filter(o=>Number.isFinite(o.x)),...p.patrol];if(p.order?.type==='house')points.push({x:785,y:240});g.strokeStyle='#edcf8277';g.beginPath();points.forEach((pt,i)=>i?g.lineTo(pt.x,pt.y):g.moveTo(pt.x,pt.y));g.stroke();for(const pt of points.slice(1)){g.strokeStyle='#edcf82cc';g.strokeRect(pt.x-4/k,pt.y-4/k,8/k,8/k);}}
 g.setLineDash([]);this.rect(g,SCOUT_GATE.x+34,SCOUT_GATE.y-38,4,40,'#736044');this.rect(g,SCOUT_GATE.x+18,SCOUT_GATE.y-40,86,17,'#c4ad78');g.font='bold 9px monospace';g.fillStyle='#353827';g.textAlign='center';g.fillText('SCOUT GATE',SCOUT_GATE.x+61,SCOUT_GATE.y-28);g.textAlign='left';g.restore();
 if(s.weather==='rain'){g.save();g.strokeStyle='#b6cee233';g.lineWidth=1;g.beginPath();for(let i=0;i<70;i++){const x=(i*171+t*55)%W,y=(i*117+t*230)%H;g.moveTo(x,y);g.lineTo(x-5,y+15);}g.stroke();g.restore();}if(s.weather==='fog'){g.save();const fog=g.createLinearGradient(0,0,W,H);fog.addColorStop(0,'#bac6c233');fog.addColorStop(.5,'#b1c0b815');fog.addColorStop(1,'#bac6c249');g.fillStyle=fog;g.fillRect(0,0,W,H);g.restore();}if(s.weather==='dry'){g.save();g.fillStyle='#cda25212';g.fillRect(0,0,W,H);g.restore();}
 }
}
